import sys

def main():
    data = sys.stdin.read().split()
    if not data:
        return
    n = int(data[0])
    scores = []
    for i in range(1, len(data)):
        val = int(data[i])
        if val == -1:
            break
        scores.append(val)
    for score in scores:
        if score >= 90:
            print("Excellent")
        elif score >= 75:
            print("Good")
        elif score >= 50:
            print("Average")
        elif score >= 35:
            print("Pass")
        else:
            print("Fail")

main()
